				}
			}
		}

		// For a=1: T = 1+p, p = T-1 must be prime.
		for _, d := range divisors {
			if d < 3 {
				continue
			}
			p := d - 1
			if isPrime(p) {
				count += solve(A / d)
			}
		}

		// For a >= 2:
		// p^a < A => p < A^(1/a)
