				}
				if T > A {
					continue
				}
				if A%T == 0 {
					count += solve(A / T)
				}
			}
		}

		memo[A] = count
		return count
	}

	result := solve(A)
	fmt.Println(result)
}

func isPrime(n int64) bool {
