	// Helper: check if a number is prime.
	func isPrime(n int64) bool {
		if n < 2 {
			return false
		}
		if n == 2 {
			return true
		}
		if n%2 == 0 {
			return false
		}
		for i := int64(3); i*i <= n; i += 2 {
			if n%i == 0 {
				return false
			}
		}
		return true
	}

	// Helper: for a given D and a, find p such that 1+p+...+p^a = D.
	// We can use binary search for p.
	func findP(D int64, a int) (int64, bool) {
		// S(p,a) = (p^(a+1)-1)/(p-1)
		// We need to find p such that S(p,a) = D.
		// S(p,a) is increasing in p for p>=2.
		// Lower bound: p=2, S(2,a) = 2^(a+1)-1
		// Upper bound: p such that p^(a+1) <= D*(p-1)+1. Roughly p <= D.
		// Let's set low=2, high=D (since p < D for a>=1).
		low := int64(2)
		high := D
		for low <= high {
			mid := (low + high) / 2
			// Compute S(mid, a)
			// S = 1 + mid + mid^2 + ... + mid^a
			// We need to be careful with overflow.
			s := int64(1)
			power := int64(1)
			valid := true
			for i := 0; i < a; i++ {
				power *= mid
				if power > D {
					valid = false
					break
				}
				s += power
				if s > D {
					valid = false
					break
				}
			}
			if !valid {
				high = mid - 1
				continue
			}
			if s == D {
				return mid, true
			} else if s < D {
				low = mid + 1
			} else {
				high = mid - 1
			}
		}
		return 0, false
	}

	// Get all divisors of n
	func getDivisors(n int64) []int64 {
		divs := []int64{}
		sqrtN := int64(math.Sqrt(float64(n)))
		for i := int64(1); i <= sqrtN; i++ {
			if n%i == 0 {
				divs = append(divs, i)
				if i != n/i {
					divs = append(divs, n/i)
				}
			}
		}
		return divs
	}

	// Recursive function: count solutions for sigma(x) = n with all prime factors of x >= minP
	var memo map[string]int64
	memo = make(map[string]int64)

	func count(n int64, minP int64) int64 {
		if n == 1 {
			return 1
		}
		key := fmt.Sprintf("%d_%d", n, minP)
		if v, ok := memo[key]; ok {
			return v
		}

		result := int64(0)
		divs := getDivisors(n)
		for _, D := range divs {
			// D is a divisor of n, representing S(p,a)
			// Try different a values
			// Max a: 2^(a+1)-1 <= D => a+1 <= log2(D+1) => a <= log2(D+1)-1
			maxA := 0
			for a := 1; ; a++ {
				// Check if 2^(a+1)-1 <= D
				// 2^(a+1) <= D+1
				if (1 << (a + 1)) - 1 > int(D) {
					break
				}
				maxA = a
			}
			for a := 1; a <= maxA; a++ {
				p, ok := findP(D, a)
				if !ok {
					continue
				}
				if p < minP {
					continue
				}
				if !isPrime(p) {
					continue
				}
				// Valid factor
				nPrime := n / D
				result += count(nPrime, p+1)
			}
		}

		memo[key] = result
		return result
	}

	// Special case: if A == 1, then x=1 is the only solution.
	if A == 1 {
		fmt.Println(1)
		return
	}

	// Start with minP = 2 (smallest prime)
	ans := count(A, 2)
	fmt.Println(ans)
