	fmt.Scan(&A)

	count := 0

	// x must be a divisor of A
	// x <= sqrt(A) for checking divisors
	limit := int64(math.Sqrt(float64(A)))
	for i := int64(1); i <= limit; i++ {
		if A%i == 0 {
			// Check x = i
			if isSolution(i, A) {
				count++
			}
			// Check x = A/i
			j := A / i
			if j != i {
				if isSolution(j, A) {
					count++
				}
			}
		}
	}

	fmt.Println(count)
}

func isSolution(x, A int64) bool {
	// J(x) = sum of divisors of x
	// We need to compute sum of divisors of x and check if it equals A
	// But x can be up to 10^12, so we need an efficient way
	// Actually, x is a divisor of A, so x <= A <= 10^12
	// We need to compute sigma(x) = sum of divisors of x

	// Factorize x and compute sigma(x)
	n := x
	if n == 0 {
		return false
	}

	sigma := int64(1)
	d := int64(2)
	for d*d <= n {
		if n%d == 0 {
			// d is a prime factor
			power := int64(1)
			sum := int64(1)
			for n%d == 0 {
				n /= d
				power *= d
				sum += power
			}
			sigma *= sum
		}
		d++
	}
	if n > 1 {
		sigma *= (1 + n)
	}

	return sigma == A
}
